function isWebSocketQuote(sym){return String(q(sym).source||'').startsWith('finnhub-websocket')}
function isAlpacaSnapshot(sym){return String(q(sym).source||'').startsWith('alpaca-')&&String(q(sym).source||'').endsWith('-snapshot')}
function isAlpacaStream(sym){return String(q(sym).source||'').startsWith('alpaca-iex-websocket')}
function sessionLabel(session=marketSession()){return ({overnight:'OVERNIGHT','pre-market':'PRE-MARKET',regular:'MARKET OPEN','after-hours':'AFTER-HOURS',closed:'MARKET CLOSED',weekend:'WEEKEND'})[session]||String(session||'UNKNOWN').toUpperCase()}
function sessionTone(session=marketSession()){return ({regular:'open','pre-market':'premarket','after-hours':'afterhours',overnight:'overnight',closed:'closed',weekend:'closed'})[session]||'closed'}
function sessionCountdown(ms){const diff=Math.max(0,num(ms)-Date.now());if(!diff)return '';const mins=Math.max(1,Math.ceil(diff/60000));if(mins<60)return `${mins}m`;const h=Math.floor(mins/60),m=mins%60;if(h<24)return `${h}h${m?` ${m}m`:''}`;const d=Math.floor(h/24),rh=h%24;return `${d}d${rh?` ${rh}h`:''}`}
function sessionBoundaryParts(ms,zone){if(!num(ms))return {day:'',time:''};const parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,weekday:'short',hour:'numeric',minute:'2-digit',hour12:true}).formatToParts(new Date(num(ms))),o=Object.fromEntries(parts.map(x=>[x.type,x.value])),time=`${o.hour}${o.minute==='00'?'':`:${o.minute}`} ${o.dayPeriod}`;return {day:o.weekday||'',time}}
function sessionBoundarySummary(ms){if(!num(ms))return '';const et=sessionBoundaryParts(ms,'America/New_York'),pt=sessionBoundaryParts(ms,'America/Los_Angeles');return et.day===pt.day?`${et.day} ${et.time} ET · ${pt.time} PT`:`${et.day} ${et.time} ET · ${pt.day} ${pt.time} PT`}
function updateMarketSessionContext(){const host=$('#market-session-context'),label=$('#market-session-label'),detail=$('#market-session-detail');if(!host||!label||!detail)return;const session=marketSession(),primary=sessionLabel(session),at=num(runtime?.feed?.sessionBoundaryAt),action=String(runtime?.feed?.sessionBoundaryAction||'').trim(),remaining=sessionCountdown(at),clock=sessionBoundarySummary(at);let secondary='';if((session==='weekend'||session==='closed')&&action&&at)secondary=`${action} · ${clock}`;else if(['pre-market','regular','after-hours','overnight'].includes(session)&&action&&at)secondary=`${action}${remaining?` in ${remaining}`:''} · ${clock}`;else if(action&&at)secondary=`${action} · ${clock}`;else secondary=session==='weekend'?'Next overnight timing unavailable':'Session status';label.textContent=primary;detail.textContent=secondary;host.className=`market-session-context ${sessionTone(session)}`;host.title=`${primary} · ${secondary}`;host.setAttribute('aria-label',`${primary}. ${secondary}`)}
function sidebarHealthEntries(health){const h=health&&typeof health==='object'?health:{},priority=['quotes','quotes-rest','alpaca-stream','alpaca-live','history','fundamentals','news','earnings','filings','global-direct','fx-direct','macro-rates','provider-capabilities','cache-refresh','weekly-integrity','scanner','vix','ai'];return priority.map(k=>[k,Object.prototype.hasOwnProperty.call(h,k)?h[k]:'Not initialized'])}
