function deskRegimeDescription(kind){return kind==='day'?'Intraday SPY, QQQ, IWM, XLK, and VIX context.':kind==='swing'?'Multi-day trend, breadth, technology leadership, and volatility.':'Long-term trend, participation, rates, and volatility.'}
function regimeQuotePill(sym){const qq=q(sym),price=num(qq.price),change=num(qq.changePercent),st=quoteState(sym);return `<span class="regime-quote-pill" title="${esc(st.label)} · ${esc(st.detail||'')}"><b>${esc(sym)}</b><strong>${price?`$${money(price)}`:'—'}</strong><em class="${change>0?'positive':change<0?'negative':'muted'}">${price?pct(change):'No Data'}</em></span>`}
