function secHorizonContext(sym,kind){const filings=researchFilingsFor(sym),days=kind==='day'?2:kind==='swing'?14:120,recent=filings.filter(f=>dateAgeDays(f.filedAt)<=days),material=recent.filter(f=>['material','offering','insider','ownership'].includes(String(f.category||'').toLowerCase())),x=runtime?.secIntelligence?.[sym];return {filings,recent,material,intelligence:x,risk:x?.offeringRisk||'Low'}}
function secHorizonCard(sym,kind){const x=secHorizonContext(sym,kind);if(kind==='day'){const f=x.material[0];if(!f)return '';return `<section class="card horizon-intel-card warning"><span class="eyebrow">Catalyst · SEC Filing</span><h3>${esc(secFilingMeaning(f))}</h3><p>${esc(f.form)} · ${dateOnly(f.filedAt)} · ${esc(f.description||f.meaning||'Material filing')}</p><button class="btn tiny ghost" data-research="${esc(sym)}" data-research-origin="day">Review Catalyst</button></section>`}if(kind==='swing'){const f=x.material[0];const status=f?'MATERIAL UPDATE':'CLEAR';return `<section class="card horizon-intel-card ${f?'warning':'positive'}"><span class="eyebrow">Filing / Catalyst Risk</span><h3>${status}</h3><p>${f?`${esc(secFilingMeaning(f))} · ${dateOnly(f.filedAt)}`:'No material recent SEC filing in the swing window.'}</p><button class="btn tiny ghost" data-research="${esc(sym)}" data-research-origin="swing">Review Filings</button></section>`}return secIntelligenceSummary(sym)}
function aiEvidenceFingerprint(sym,horizon='research'){
 const target=String(sym||'').toUpperCase(),parts=[target,horizon],eid=(String(runtime?.evidenceSnapshot?.symbol||'').toUpperCase()===target?String(runtime?.evidenceSnapshot?.id||''):'');parts.push(`evidence:${eid}`);
 // AI refreshes are material-evidence driven. Raw quote ticks and successful
 // no-change polling timestamps must not make an otherwise current opinion stale.
 for(const k of ['day','swing','long']){const p=planFor(target,k),r=tradeReadiness(target,k),bucket=Math.round(num(p.score)/5)*5;parts.push(`${k}:${bucket}:${actionState(p)}:${r.status}`)}
 const sec=runtime?.secIntelligence?.[target]||{};parts.push(`sec:${num(sec.insiderBuys)}:${num(sec.insiderSells)}:${num(sec.insiderOthers)}:${String(sec.offeringRisk||'')}:${String(sec.latestFiling||'')}`);
 const ev=(runtime?.earnings||[]).filter(x=>String(x.symbol||'').toUpperCase()===target).map(x=>[x.date||'',x.hour||'',x.epsEstimate??'',x.epsActual??'',x.revenueEstimate??'',x.revenueActual??'',x.guidanceStatus||''].join(':')).sort();parts.push(`earn:${ev.join(';')}`);
 const materialNews=newsForSymbol(target).filter(n=>v151Materiality(`${n.headline||''} ${n.summary||''}`)!=='CONTEXT').slice(0,3).map(n=>`${num(n.datetime)}:${String(n.headline||'').trim()}`);parts.push(`news:${materialNews.join(';')}`);
 const f=runtime?.fundamentals?.[target]||{};parts.push(`fund:${num(f.revenueGrowth).toFixed(3)}:${num(f.epsGrowth).toFixed(3)}:${num(f.grossMargin).toFixed(3)}:${num(f.operatingMargin).toFixed(3)}:${num(f.roe).toFixed(3)}:${num(f.netMargin).toFixed(3)}:${num(f.debtToEquity).toFixed(3)}:${num(f.freeCashFlow).toFixed(0)}`);
 const cat=runtime?.catalystReactions?.[target]||{};parts.push(`risk:${String(cat.triggerType||'')}:${!!cat.extremeVolatility}:${!!cat.liquidityRisk}:${String(cat.holdFadeState||'')}`);
 return parts.join('|')
}
function aiResultKey(sym,horizon='research',reviewType='ticker',question=''){const q=reviewType==='custom'?String(question||'').trim().toLowerCase().slice(0,240):'';return `${String(sym||'').toUpperCase()}|${horizon}|${reviewType}|${q}|${aiEvidenceFingerprint(sym,horizon)}`}
