function aiProviderState(id){const p=state?.providerStatus?.[id];if(!aiProviderConfigured(id))return {label:'NOT CONFIGURED',light:'yellow',detail:'Add an API key in Settings.'};if(p?.ok)return {label:'READY',light:'green',detail:p.message||'Connection verified.'};if(p&&p.status==='billing required')return {label:'BILLING REQUIRED',light:'red',detail:p.message||'API billing is required.'};if(p&&p.status==='rate limited')return {label:'RATE LIMITED',light:'yellow',detail:p.message||'Current provider rate limit reached.'};if(p&&!p.ok)return {label:'CHECK CONNECTION',light:'red',detail:p.message||'Connection test failed.'};return {label:'CONFIGURED',light:'cyan',detail:'API key saved. Run Save & Test to verify.'}}
