function aiHorizonLabel(h){return h==='day'?'Day Trade':h==='swing'?'Swing':h==='long'?'Long-Term':'Cross-Horizon Research'}

function aiContextSummaryMarkup(sym){const h=aiOriginHorizon,label=aiHorizonLabel(h),ctx=buildAIClientContext(sym,h);let score='Cross-horizon';if(['day','swing','long'].includes(h)&&ctx.deterministic)score=`${Math.round(ctx.deterministic.score)}/100 · ${titleCaseText(actionState(ctx.deterministic))}`;return `<section class="ai-context-received"><div><small>Received context</small><b>${esc(aiOrigin==='research'?'Research':aiOrigin==='day'?'Day Trade':aiOrigin==='swing'?'Swing':aiOrigin==='long'?'Long-Term':aiOrigin==='discovery'?'Discovery':'Dashboard')} → ${esc(label)}</b></div><div><small>Deterministic setup</small><b>${esc(score)}</b></div><div><small>Earnings</small><b>${esc(earningsCompactLine(sym))}</b></div><div><small>Evidence freshness</small><b>${esc(quoteState(sym).label)}</b></div></section>`}
async function runAIRequest(kind='ticker'){const qtext=$('#ai-question')?.value||'',out=$('#ai-output'),meta=$('#ai-response-meta'),sym=String(aiSymbol||state?.ui?.selectedTicker||'SPY').toUpperCase(),horizon=aiOriginHorizon||'none',key=aiResultKey(sym,horizon,kind,qtext);$$('[data-ai]').forEach(x=>x.classList.toggle('primary',x.dataset.ai===kind));const cached=aiResearchResults[key];if(cached){cached._generatedAt=Date.now();render();const m=$('#ai-response-meta');if(m)m.textContent=`Cached ${kind==='risk'?'Risk Review':kind==='news'?'Catalyst Review':kind==='custom'?'Custom Question':'Research Confirmation'} · evidence unchanged`;return}const activeBtn=$('[data-ai-run-review]');if(activeBtn){activeBtn.disabled=true;activeBtn.dataset.originalText=activeBtn.textContent;activeBtn.textContent='Analyzing…'}if(out)out.innerHTML=`<div class="empty">Analyzing ${esc(sym)} ${esc(aiHorizonLabel(horizon))} context…</div>`;if(meta)meta.textContent=`Using ${aiProviderMeta().name}…`;try{const clientContext=buildAIClientContext(sym,horizon),res=await api('/api/ai/generate',{kind:kind==='custom'?'':kind,question:qtext,ticker:sym,scopeType:'watchlist',watchlistId:['day','swing','long'].includes(horizon)?deskWL(horizon).id:deskWL('swing').id,clientContext});aiResearchResults[key]={...res,_symbol:sym,_horizon:horizon,_reviewType:kind,_question:kind==='custom'?qtext:'',_generatedAt:Date.now(),_fingerprint:aiEvidenceFingerprint(sym,horizon)};render();const m=$('#ai-response-meta');if(m)m.textContent=aiResponseMetaText(res)}catch(e){if(out)out.innerHTML=`<div class="empty negative">${esc(e.message||'AI review could not be completed.')}</div>`;if(meta)meta.textContent=`${aiProviderMeta().name} · Request failed`}finally{const b=$('[data-ai-run-review]');if(b){b.disabled=false;if(b.dataset.originalText)b.textContent=b.dataset.originalText}}}
function openAIFor(sym,origin='research',horizon='none',autoRun=true){const target=String(sym||state?.ui?.selectedTicker||'SPY').toUpperCase();if(origin==='research'&&!v151ResearchReadyForAI(target)){toast('Research Evidence Not Ready','Refresh and reconcile the complete sourced Research package before asking AI.','warning');return}aiSymbol=target;aiOrigin=origin||'research';aiOriginHorizon=['day','swing','long'].includes(horizon)?horizon:'none';aiReviewMode='ticker';aiAutoRun=!!autoRun;api('/api/ui/ticker',{symbol:aiSymbol}).catch(()=>{});setPage('ai')}
function aiResultMarkup(sym){const r=latestAIResultFor(sym);if(!r)return `<div id="ai-output" class="ai-result-empty">The selected symbol and horizon evidence are preloaded. Run Research Confirmation for a concise second opinion.</div>`;const horizon=r.bestFitHorizon,hl=aiHorizonLabel(horizon),verdict=titleCaseText(r.verdict||'Informational'),caseList=(title,items,tone)=>`<div class="ai-case ${tone}"><small>${title}</small><ul>${(items||[]).slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Not established from current evidence</li>'}</ul></div>`,evidence=(r.evidenceIds||[]).slice(0,8);return `<section id="ai-output" class="ai-result-card ${String(r.verdict||'informational').toLowerCase()}"><div class="ai-verdict-row"><div><span class="eyebrow">${esc(r._reviewType==='risk'?'Risk Review':r._reviewType==='news'?'Catalyst Review':r._reviewType==='custom'?'Custom Question':'Research Confirmation')}</span><h2>${esc(verdict)}</h2><p>${esc(r.summary||r.nextAction||'Review completed.')}</p></div><div class="ai-confidence"><small>Analysis confidence</small><b>${Math.round(num(r.confidence))}%</b><em>Not win probability</em></div></div><div class="ai-case-grid">${caseList('Bull case',r.bullCase,'positive')}${caseList('Base case',r.baseCase,'neutral')}${caseList('Bear case',r.bearCase,'negative')}</div><div class="ai-result-grid"><div><small>Best-fit horizon</small><b>${esc(hl)}</b></div><div><small>Key reasons</small><ul>${(r.reasons||[]).slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>None supplied</li>'}</ul></div><div><small>Risks</small><ul>${(r.risks||[]).slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>None identified</li>'}</ul></div><div><small>Catalyst</small><b>${esc(r.catalyst||'None identified')}</b></div><div><small>Contradictions</small><ul>${(r.contradictions||[]).slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>No material contradiction identified</li>'}</ul></div><div><small>Missing evidence</small><ul>${(r.missingEvidence||[]).slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>No required gap identified</li>'}</ul></div></div><div class="ai-grounding-strip"><div><small>Evidence package</small><b>${esc(r.evidencePackageId||'—')}</b></div><div><small>Canonical snapshot</small><b>${esc(r.evidenceSnapshotId||'—')}</b></div><div><small>Routing</small><b>${esc(titleCaseText(r.routePolicy||state?.settings?.aiRoutingMode||'manual'))}${r.cacheHit?' · CACHE HIT':''}</b></div></div>${evidence.length?`<details class="ai-evidence"><summary>Grounding · ${evidence.length} cited evidence ID${evidence.length===1?'':'s'}</summary><div class="ai-evidence-ids">${evidence.map(x=>`<code>${esc(x)}</code>`).join('')}</div>${r.details?`<p>${esc(r.details)}</p>`:''}</details>`:(r.details?`<details class="ai-evidence"><summary>Evidence & details</summary><p>${esc(r.details)}</p></details>`:'')}${(r.safetyWarnings||[]).length?`<div class="ai-safety-note"><b>External-content safety</b><span>${esc((r.safetyWarnings||[]).join(' · '))}</span></div>`:''}<div class="button-row ai-next-actions"><button class="btn ghost" data-ai-open-research="${esc(sym)}">Open Research</button>${['day','swing','long'].includes(horizon)?`<button class="btn primary" data-ai-open-desk="${horizon}:${esc(sym)}">Open ${esc(hl)}</button>${!(deskWL(horizon).symbols||[]).includes(sym)?`<button class="btn" data-ai-add-desk="${horizon}:${esc(sym)}">Add to ${esc(hl)}</button>`:''}`:''}</div><p class="research-footnote">AI is advisory. It cannot trade, change Action/Score, or add/remove a symbol without your explicit click. Analysis is evidence-grounded, and external content is untrusted data.</p></section>`}
function renderAI(){
 const id=activeAIProvider(),meta=aiProviderMeta(id),st=aiProviderState(id),display=aiProviderDisplay(id),mode=id==='openrouter'?openRouterModeInfo().label:'',sym=String(aiSymbol||state?.ui?.selectedTicker||'SPY').toUpperCase(),symbols=allResearchSymbols(),reviewLabel=aiReviewMode==='risk'?'Risk Review':aiReviewMode==='news'?'Catalyst Review':aiReviewMode==='custom'?'Custom Question':'Research Confirmation',originLabel=aiOrigin==='research'?'Research':aiOrigin==='day'?'Day Trade':aiOrigin==='swing'?'Swing':aiOrigin==='long'?'Long-Term':aiOrigin==='discovery'?'Discovery':'Dashboard';
 const reviews=[['ticker','Research Confirmation'],['risk','Risk Review'],['news','Catalyst Review'],['custom','Custom Question']];
 return `<div class="page ai-page">${pageHead('AI Copilot','A context-aware second opinion on the symbol you were already reviewing.','ai','','none')}<section class="card ai-engine-card ai-engine-${id}"><div class="ai-engine-main"><div class="ai-engine-orb ${st.light}"><span></span><i></i></div><div class="ai-engine-copy"><span class="eyebrow">AI Engine</span><h2>${esc(meta.name)} <small>${esc(meta.role)}</small></h2><p>${id==='openrouter'?`${esc(mode)} · ${esc(openRouterModeInfo().summary)}`:esc(display.model)}</p></div></div><div class="ai-engine-state"><span>${statusDot(st.light,st.label)}${esc(st.label)}</span><small>${esc(st.detail)}</small></div><button class="btn ghost" data-jump="settings" data-settings-target="ai-integration">Manage AI</button></section><section class="card ai-workspace"><div class="ai-target-section"><span class="eyebrow">Research Target</span><div class="ai-target-paths"><label><small>Choose from List</small><select data-ai-symbol aria-label="Choose AI research target">${symbols.map(s=>`<option value="${esc(s)}" ${s===sym?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label><small>Add Symbol</small><span><input data-ai-symbol-input placeholder="Ticker" maxlength="8" aria-label="Enter any ticker"><button class="btn tiny" data-ai-symbol-load>Load</button></span></label></div><h2>${esc(sym)} · ${esc(aiHorizonLabel(aiOriginHorizon))}</h2><p>Opened from ${esc(originLabel)}. Context is preloaded; verify the received context below before asking AI to review it.</p></div>${aiContextSummaryMarkup(sym)}<section class="ai-review-workspace"><div class="ai-review-heading"><div><span class="eyebrow">Choose Review</span><h3>What should AI validate?</h3><p>Optional question appears when Custom Question is selected.</p></div></div><div class="ai-review-selector">${reviews.map(([k,l])=>`<button class="ai-review-choice ${aiReviewMode===k?'active':''}" data-ai-review-choice="${k}">${l}</button>`).join('')}</div>${aiReviewMode==='custom'?`<div class="field ai-custom-question"><label>Custom Question</label><textarea id="ai-question" rows="3" placeholder="What is the biggest reason this setup could fail?"></textarea></div>`:`<textarea id="ai-question" hidden></textarea>`}<div class="ai-run-row"><button class="btn primary" data-ai-run-review="${aiReviewMode}">Run ${esc(reviewLabel)}</button><span class="ai-active-provider">Using ${esc(meta.name)}${mode?' · '+esc(mode):''}</span></div></section>${aiResultMarkup(sym)}<div id="ai-response-meta" class="ai-response-meta">Provider: ${esc(meta.name)}${id==='openrouter'?' · '+esc(mode):' · '+esc(display.model)}</div></section></div>`
}
function aiResponseMetaText(res){const provider=res.providerLabel||aiProviderMeta(res.provider).name,actual=modelDisplayName(res.model),parts=[res.cacheHit?'Material-evidence cache hit':`Generated with ${provider}`];if(actual)parts.push(actual);if(res.routePolicy)parts.push(`${titleCaseText(res.routePolicy)} routing`);if(res.mode)parts.push(String(res.mode).toUpperCase());if(num(res.latencyMs)&&!res.cacheHit)parts.push(`${(num(res.latencyMs)/1000).toFixed(1)}s`);const tokens=num(res.inputTokens)+num(res.outputTokens);if(tokens)parts.push(`${tokens.toLocaleString()} tokens`);if(num(res.cost))parts.push(`$${num(res.cost).toFixed(4)}`);if(res.fallback)parts.push('Fallback used');return parts.join(' · ')}
function providerStatus(name){const p=state?.providerStatus?.[name];if(!p)return '<div class="status-box muted">Not tested in this installation.</div>';return `<div class="status-box ${p.ok?'positive':'negative'}"><b>${esc(titleCaseText(p.status))}</b> · ${esc(p.message)}<br><span class="muted">${timePair(Date.parse(p.checkedAt))}</span></div>`}
function fmtBytes(n){n=num(n);return n>=1048576?`${(n/1048576).toFixed(1)} MB`:n>=1024?`${(n/1024).toFixed(1)} KB`:`${n||0} B`}
function vixDiagnosticsCard(){const vx=q('VIX'),health=String(runtime?.health?.vix||'Not initialized'),last=num(runtime?.lastUpdated?.vix),source=String(vx.source||'');let sourceLabel='Unavailable';if(source.startsWith('finnhub-vix:'))sourceLabel='Finnhub direct index';else if(source.startsWith('twelvedata-vix:'))sourceLabel='Twelve Data direct index';else if(source==='cboe-vix-official-close')sourceLabel='Cboe official close';else if(source&&num(vx.price))sourceLabel=source.includes('cache')?'Real cache':source;const tone=sidebarHealthTone(health),stateText=num(vx.price)?`${money(vx.price)} · ${sourceLabel}`:'Unavailable';return `<div class="vix-diagnostic-card"><span>${statusDot(tone==='green'?'green':tone==='red'?'red':'yellow','VIX')}VIX</span><b>${esc(stateText)}</b><small>${esc(health)}${last?' · '+esc(timePair(last)):''}</small></div>`}
function feedDiagnostics(){const f=runtime?.feed||{},lastFinnhub=num(f.lastTradeAt),lastAlpaca=num(f.lastAlpacaAt),lastAlpacaStream=num(f.lastAlpacaStreamAt),count=(f.subscribedSymbols||[]).length,alpacaCount=(f.alpacaSubscribedSymbols||[]).length,stateLabel=(f.feedState==='streaming'||f.feedState==='alpaca-streaming'||f.feedState==='overnight-streaming')?liveLabelForSession(f.marketSession):f.feedState==='snapshot-live'?'SNAPSHOT':f.feedState==='reconnecting'?'RECONNECTING':sessionLabel(f.marketSession),light=(f.feedState==='streaming'||f.feedState==='alpaca-streaming'||f.feedState==='overnight-streaming')?'green':f.feedState==='reconnecting'?'red':'yellow';return `<section class="settings-section feed-diagnostics"><div class="section-heading-row"><div><h2>Live Data Diagnostics</h2><p>Detailed runtime health without creating additional subscriptions.</p></div>${statusDot(light,stateLabel)}</div><div class="diagnostic-grid"><div><span>Market Session</span><b>${esc(sessionLabel(f.marketSession))}</b></div><div><span>Finnhub WebSocket</span><b>${f.webSocketConnected?'Connected':'Disconnected'}</b><small>${count} active · ${num(f.finnhubMaxSymbols)||50} max · ${Math.max(0,(num(f.finnhubMaxSymbols)||50)-count)} available</small></div><div><span>Finnhub Last Trade</span><b>${lastFinnhub?timePair(lastFinnhub):'No recent trade'}</b><small>${esc(f.lastTradeSymbol||'')}</small></div><div><span>Alpaca IEX Fallback</span><b>${f.alpacaWebSocketConnected?'Connected':'Disconnected'}</b><small>${alpacaCount} active · ${num(f.alpacaMaxSymbols)||30} max · ${Math.max(0,(num(f.alpacaMaxSymbols)||30)-alpacaCount)} available</small></div><div><span>Alpaca IEX Last Update</span><b>${lastAlpacaStream?timePair(lastAlpacaStream):'No recent update'}</b><small>${esc(f.lastAlpacaStreamSymbol||'')}</small></div><div><span>Alpaca Snapshot / Overnight</span><b>${esc(titleCaseText(String(f.alpacaLiveFeed||'Idle')))}</b><small>${lastAlpaca?timePair(lastAlpaca):'No recent snapshot'} ${esc(f.lastAlpacaSymbol||'')}</small></div><div><span>Overnight Mode</span><b>${esc(titleCaseText(String(f.overnightDataMode||state?.settings?.overnightDataMode||'auto')))}</b><small>Live overnight: ${f.overnightLiveAvailable?'Available':'Not detected'}</small></div><div><span>Scanner</span><b>${esc(titleCaseText(runtime?.scanner?.status||'Idle'))}</b><small>${esc(runtime?.scanner?.message||'')}</small></div><div><span>Live Market Coverage</span><b>${num(f.liveSymbols)} live · ${(f.snapshotSymbols||[]).length} snapshot</b><small>${num(f.trackedSymbols)} tracked · Finnhub + Alpaca IEX + snapshot pool</small></div>${vixDiagnosticsCard()}</div></section>`}
