function watchlistEditInProgress(){const active=document.activeElement;if(active?.matches?.('[data-add-input]'))return true;if(page==='discovery'&&active?.matches?.('.discovery-page select, .discovery-page input, .discovery-page textarea'))return true;return Object.values(watchlistDraft).some(v=>String(v||'').trim()!=='')}
function quoteAffectsPage(sym,target=page){const symbol=String(sym||'').toUpperCase();if(!symbol)return true;if(target==='dashboard')return COMMON_MARKET_SYMBOLS.includes(symbol)||['day','swing','long'].some(k=>deskWL(k).symbols.includes(symbol));if(target==='market-intelligence')return COMMON_MARKET_SYMBOLS.includes(symbol)||symbol===String(runtime?.marketIntelligence?.selectedSymbol||state?.ui?.selectedTicker||'').toUpperCase();if(['day','swing','long'].includes(target))return COMMON_MARKET_SYMBOLS.includes(symbol)||deskWL(target).symbols.includes(symbol);if(target==='discovery')return COMMON_MARKET_SYMBOLS.includes(symbol)||discoveryWL().symbols.includes(symbol)||(runtime?.scanner?.results||[]).some(r=>String(r.symbol||'').toUpperCase()===symbol)||(runtime?.scanner?.radar?.candidates||[]).some(r=>String(r.symbol||'').toUpperCase()===symbol);if(target==='research')return COMMON_MARKET_SYMBOLS.includes(symbol)||symbol===String(researchSymbol||'').toUpperCase();return false}
function scheduleLiveRender(changedSymbol=''){perfMetrics.renderRequests++;if(changedSymbol&&!quoteAffectsPage(changedSymbol)){perfMetrics.renderSkipped++;return}clearTimeout(window.__renderTimer);window.__renderTimer=setTimeout(()=>{if(watchlistEditInProgress()){scheduleLiveRender(changedSymbol);return}perfMetrics.renderExecuted++;render()},250)}
function syncSidebarScrollState(){const scroll=$('#sidebar-scroll'),side=$('.sidebar');if(!scroll||!side)return;const max=Math.max(0,scroll.scrollHeight-scroll.clientHeight);side.classList.toggle('sidebar-has-scroll',max>2);side.classList.remove('sidebar-can-up','sidebar-can-down')}
function bindSidebarScroll(){const scroll=$('#sidebar-scroll');if(!scroll||scroll.dataset.bound==='1')return;scroll.dataset.bound='1';let timer=0;const pulse=()=>{scroll.classList.add('is-scrolling');clearTimeout(timer);timer=setTimeout(()=>scroll.classList.remove('is-scrolling'),1250);syncSidebarScrollState()};scroll.addEventListener('scroll',pulse,{passive:true});scroll.addEventListener('wheel',pulse,{passive:true});scroll.addEventListener('mouseenter',syncSidebarScrollState,{passive:true});if(typeof ResizeObserver!=='undefined')new ResizeObserver(syncSidebarScrollState).observe(scroll);window.addEventListener('resize',syncSidebarScrollState,{passive:true});requestAnimationFrame(syncSidebarScrollState)}
