 const zoneClock=(zone)=>{const now=new Date(),parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,timeZoneName:'short',hour:'numeric'}).formatToParts(now),abbr=parts.find(x=>x.type==='timeZoneName')?.value||'';return {date:now.toLocaleDateString('en-US',{timeZone:zone,month:'short',day:'2-digit',year:'numeric'}).toUpperCase(),time:now.toLocaleTimeString('en-US',{timeZone:zone,hour:'numeric',minute:'2-digit',second:'2-digit'}),abbr}};const updateClock=()=>{const eastern=zoneClock('America/New_York'),pacific=zoneClock('America/Los_Angeles'),et=$('#clock-et'),pt=$('#clock-pt'),ed=$('#date-et'),pd=$('#date-pt'),ez=$('#zone-et'),pz=$('#zone-pt');if(et)et.textContent=eastern.time;if(ez)ez.textContent='ET';if(ed){ed.textContent=eastern.date;ed.title=new Date().toLocaleDateString('en-US',{timeZone:'America/New_York',weekday:'long',year:'numeric',month:'long',day:'numeric'})}if(pt)pt.textContent=pacific.time;if(pz)pz.textContent='PT';if(pd){pd.textContent=pacific.date;pd.title=new Date().toLocaleDateString('en-US',{timeZone:'America/Los_Angeles',weekday:'long',year:'numeric',month:'long',day:'numeric'})}updateMarketSessionContext();updateMacroEventBanner()};updateClock();setInterval(updateClock,1000);setInterval(()=>{if(state&&runtime){updateTickerTape();const health=headerDataHealth(),status=$('#runtime-status');if(status)status.title=health.detail}},5000);window.addEventListener('resize',scheduleTickerMotion,{passive:true});if(typeof ResizeObserver!=='undefined'){const viewport=$('.ticker-viewport');if(viewport)new ResizeObserver(scheduleTickerMotion).observe(viewport)};
