function optionsDashboardPulse(){const items=Object.values(runtime?.options||{}).filter(o=>['BULLISH','BEARISH'].includes(String(o.bias||''))).sort((a,b)=>(num(b.callVolume)+num(b.putVolume))-(num(a.callVolume)+num(a.putVolume))).slice(0,4);if(!items.length)return '';return `<section class="card options-pulse"><div class="card-head"><div><span class="eyebrow">Options Intelligence</span><h3>Material positioning context</h3><p>Horizon-aware context only · deterministic Scores unchanged.</p></div><span class="context-formula-note">${broadOptionsRegimeComponent()!=null?'Broad SPY/QQQ context correlated to Market Regime':'Ticker context only'}</span></div><div class="options-intel-list">${items.map(o=>`<button class="options-intel-row bias-${String(o.bias).toLowerCase()}" data-research="${esc(o.symbol)}" data-research-origin="dashboard"><span class="options-symbol"><b>${esc(o.symbol)}</b><i>${esc(titleCaseText(o.bias))}</i></span><span class="options-metrics"><em><small>P/C</small><b>${num(o.putCallVolume)?num(o.putCallVolume).toFixed(2):'—'}</b></em><em><small>IV</small><b>${num(o.averageIv)?pct(num(o.averageIv)*100):'—'}</b></em><em><small>ΔIV</small><b>${num(o.ivChange)?`${num(o.ivChange)>0?'+':''}${num(o.ivChange).toFixed(1)}pp`:'—'}</b></em><em><small>Expected</small><b>${num(o.expectedMove)?'$'+money(o.expectedMove):'—'}</b></em></span><span class="options-source">${esc(o.feed||o.state||'')} · ${o.updatedAt?ageText(Date.now()-num(o.updatedAt)):'No timestamp'}</span></button>`).join('')}</div></section>`}
