function dashboardCard(kind){const cfg=deskCfg[kind],enabled=deskEnabled(kind),plans=enabled?topPlans(kind,99):[],p=plans[0];return `<section class="card summary-card ${enabled?'':'engine-off'}"><div class="card-head"><div><span class="eyebrow">Horizon Overview</span><h2>${cfg.title}</h2><p>${enabled?`${cfg.horizon} · ${plans.length} candidate${plans.length===1?'':'s'}`:'Engine off'}</p></div><button class="btn small ghost" data-jump="${kind}">Open</button></div>${enabled&&p?`<div class="top-pick dashboard-top-pick"><button class="top-pick-main" data-jump="${kind}" data-symbol="${p.sym}"><span><strong>${p.sym}</strong><small>${titleCaseText(actionState(p))} · ${Math.round(p.score)}/100 · ${tradeReadiness(p.sym,kind).status}</small></span><span class="right"><strong>$${money(p.price)}</strong><small>${esc(globalContextLine(p.sym,kind))}</small></span></button><button class="btn tiny ghost top-pick-research" data-research="${p.sym}" data-research-origin="dashboard">Research</button></div>`:enabled?'<div class="empty">No candidates.</div>':'<div class="empty">Turn on the engine to resume desk calculations.</div>'}</section>`}
function concentrationAttentionForSymbol(sym){const pairs=(runtime?.validationLearning?.concentration?.pairs||[]).filter(p=>(p.symbolA===sym||p.symbolB===sym)&&(p.state==='HIGH'||p.state==='ELEVATED'));if(!pairs.length)return null;const p=pairs[0];return {state:p.state,detail:`${p.symbolA}/${p.symbolB} correlation ${num(p.correlation).toFixed(2)} across ${num(p.sampleCount)} aligned returns`}}
function decisionQueuePlans(limit=5){const rows=[];for(const kind of ['day','swing','long']){if(!deskEnabled(kind))continue;for(const p of topPlans(kind,3)){const r=tradeReadiness(p.sym,kind),e=earningsIntelligence(p.sym),o=optionsFor(p.sym),concentration=concentrationAttentionForSymbol(p.sym);let priority=queuePriorityFor(p,kind,r);if(concentration?.state==='HIGH'&&priority!=='HIGH')priority='HIGH';else if(concentration?.state==='ELEVATED'&&priority==='LOW')priority='MEDIUM';rows.push({...p,deskKind:kind,readiness:r,priority,e,o,concentration,keyDriver:keyDriverForPlan(p,kind),researchState:researchStateFor(p.sym)})}}rows.sort((a,b)=>({HIGH:3,MEDIUM:2,LOW:1}[b.priority]-({HIGH:3,MEDIUM:2,LOW:1}[a.priority]))||b.score-a.score);const unique=[];for(const p of rows){if(unique.some(x=>x.sym===p.sym))continue;unique.push(p);if(unique.length>=limit)break}return unique}
