function calendarFilterOptions(rows,key){return [...new Set((rows||[]).map(x=>String(x?.[key]||'').trim()).filter(Boolean))].sort()}
function filteredEconomicCalendar(){const rows=[...(eventIntel().calendar||[])],f=marketCalendarFilters,impact=String(f.impact||'ALL').toUpperCase(),scope=String(f.scope||'US'),category=String(f.category||'ALL'),date=String(f.date||'');let out=rows.filter(x=>(impact==='ALL'||String(x.impact||'').toUpperCase()===impact)&&(scope==='ALL'||String(x.scope||'US')===scope)&&(category==='ALL'||String(x.category||'')===category)&&(!date||String(x.date||'')===date));const impactRank={HIGH:3,MEDIUM:2,LOW:1,UNKNOWN:0};out.sort((a,b)=>f.sort==='TIME_DESC'?num(b.startsAt)-num(a.startsAt):f.sort==='IMPACT'?((impactRank[String(b.impact||'').toUpperCase()]||0)-(impactRank[String(a.impact||'').toUpperCase()]||0))||num(a.startsAt)-num(b.startsAt):num(a.startsAt)-num(b.startsAt));return out}
function marketEventIntelligenceMarkup(){const e=eventIntel(),d=e.decision||{},fed=e.fed||{},news=(e.news||[]).filter(x=>['HIGH','MEDIUM'].includes(String(x.materiality||'').toUpperCase())&&!['STALE','INVALID'].includes(String(x.freshness||'').toUpperCase())).slice(0,6),allCal=e.calendar||[],cal=filteredEconomicCalendar().slice(0,20),scopes=calendarFilterOptions(allCal,'scope'),categories=calendarFilterOptions(allCal,'category'),notes=(e.notifications||[]).slice(0,6),react=(e.reactions||[]).slice(0,6);const filter=`<div class="scanner-filter-grid calendar-filter-grid"><div class="field compact"><label>Impact</label><select data-calendar-filter="impact">${['ALL','HIGH','MEDIUM','LOW'].map(v=>`<option value="${v}" ${marketCalendarFilters.impact===v?'selected':''}>${v==='ALL'?'All':titleCaseText(v)}</option>`).join('')}</select></div><div class="field compact"><label>Scope</label><select data-calendar-filter="scope"><option value="US" ${marketCalendarFilters.scope==='US'?'selected':''}>US</option><option value="GLOBAL CONTEXT" ${marketCalendarFilters.scope==='GLOBAL CONTEXT'?'selected':''}>Global Context</option><option value="ALL" ${marketCalendarFilters.scope==='ALL'?'selected':''}>All</option></select></div><div class="field compact"><label>Category</label><select data-calendar-filter="category"><option value="ALL">All</option>${categories.map(v=>`<option value="${esc(v)}" ${marketCalendarFilters.category===v?'selected':''}>${esc(titleCaseText(v))}</option>`).join('')}</select></div><div class="field compact"><label>Date</label><input type="date" data-calendar-filter="date" value="${esc(marketCalendarFilters.date||'')}"></div><div class="field compact"><label>Sort</label><select data-calendar-filter="sort">${[['TIME_ASC','Time ↑'],['TIME_DESC','Time ↓'],['IMPACT','Impact']].map(([v,l])=>`<option value="${v}" ${marketCalendarFilters.sort===v?'selected':''}>${l}</option>`).join('')}</select></div></div>`;return `<section class="settings-section event-intelligence-section"><div class="section-heading-row"><div><span class="eyebrow">Events</span><h2>Professional Event Intelligence</h2><p>Canonical News, Macro, Fed, Earnings, SEC/Catalyst and reaction evidence are correlated here. Event context may change readiness/attention, never deterministic Score/Action.</p></div>${eventIntelStateChip(d.marketRisk||d.state)}</div><div class="summary-grid"><article class="card"><small>Market Event Risk</small><h3>${esc(d.marketRisk||'DATA DEGRADED')}</h3><p>${esc((d.reasons||[])[0]||'No high-impact event window currently proven.')}</p><small>${esc(d.deterministicScoreImpact||'Deterministic score impact: NONE')}</small></article><article class="card"><small>FOMC / Fed</small><h3>${esc(fed.state||'UNAVAILABLE')}</h3><p>${esc(fed.name||'No sourced Fed event')}</p><small>${fed.startsAt?eventCalendarTime(fed):esc(fed.detail||'')}</small></article></div><div class="event-intel-grid"><article class="card"><div class="card-head compact"><h3>Material News</h3><span class="count-pill">${news.length}</span></div><div class="compact-list">${news.map(x=>`<div class="compact-row"><b>${esc((x.symbols||[]).slice(0,2).join(', ')||'Market')} · ${esc(x.materiality||'CONTEXT')}</b><span>${esc(x.headline)} · ${esc((x.supportingSources||[x.source]).join(' + '))} · ${esc(x.freshness||'UNAVAILABLE')}</span></div>`).join('')||'<div class="empty">No current material clustered news.</div>'}</div></article><article class="card economic-calendar-card"><div class="card-head compact"><div><h3>Economic Calendar</h3><small>US primary · selective Global Context only · ${cal.length}/${allCal.length} shown · actual / forecast / previous / surprise remain source-truthful</small></div><span class="count-pill">${cal.length}</span></div>${filter}<div class="compact-list">${cal.map(x=>`<div class="compact-row"><b>${esc(x.name)} · ${esc(x.category||'OTHER')} · ${esc(x.impact||'UNKNOWN')}</b><span>${eventIntelStateChip(x.state)} ${eventCalendarTime(x)} · ${esc(x.scope||'US')}${x.scope==='GLOBAL CONTEXT'&&x.region?` (${esc(x.region)})`:''} · ${esc(x.source||'—')} · A ${x.actual==null?'—':num(x.actual).toFixed(2)} / F ${x.forecast==null?'—':num(x.forecast).toFixed(2)} / P ${x.previous==null?'—':num(x.previous).toFixed(2)}${x.surprise!=null?` · surprise ${num(x.surprise)>=0?'+':''}${num(x.surprise).toFixed(2)}${esc(x.unit||'')}`:''}</span></div>`).join('')||'<div class="empty">No calendar events match the selected filters.</div>'}</div></article><article class="card"><div class="card-head compact"><h3>Smart Notifications</h3><span class="count-pill">${notes.length}</span></div><div class="compact-list">${notes.map(x=>`<div class="compact-row"><b>${esc(x.title)}</b><span>${esc(x.kind)} · ${esc(x.message)}</span></div>`).join('')||'<div class="empty">No new material state-change notification.</div>'}</div></article><article class="card"><div class="card-head compact"><h3>Reaction Intelligence</h3><span class="count-pill">${react.length}</span></div><div class="compact-list">${react.map(x=>`<div class="compact-row"><b>${esc(x.symbol||'Market')} · ${esc(x.eventType||'EVENT')}</b><span>${esc(x.phase||'—')} · ${esc(x.state||'—')}${num(x.movePct)?` · ${pctSigned(x.movePct)}`:''}${num(x.relativeVolume)?` · RVOL ${num(x.relativeVolume).toFixed(2)}×`:''}</span></div>`).join('')||'<div class="empty">No material reaction evidence captured.</div>'}</div></article><article class="card"><div class="card-head compact"><h3>Event → Decision</h3><span class="count-pill">${(d.affectedSymbols||[]).length}</span></div><div class="compact-list">${(d.queueActions||[]).slice(0,6).map(x=>`<div class="compact-row"><b>Review</b><span>${esc(x)}</span></div>`).join('')||'<div class="empty">No event-driven queue action.</div>'}</div></article></div></section>`}
function researchEventIntelligenceMarkup(sym){const x=eventIntelForSymbol(sym);if(!(x.news.length||x.reactions.length||x.notifications.length||x.risk))return `<section class="card"><div class="card-head"><div><h2>Event Intelligence</h2><p>No current material event intelligence is mapped to ${esc(sym)}.</p></div></div></section>`;return `<section class="card"><div class="card-head"><div><h2>Event Intelligence</h2><p>Ticker-specific event context from the canonical v16.2 event layer.</p></div>${x.risk?eventIntelStateChip('EVENT RISK'):''}</div>${x.risk?`<div class="compact-row"><b>Trade Readiness context</b><span>${esc(x.risk)}</span></div>`:''}<div class="research-news-list">${x.news.slice(0,4).map(n=>`<article><div class="meta"><span>${esc(n.materiality)} · ${esc(n.category)}</span><span>${n.publishedAt?ageText(Date.now()-num(n.publishedAt)*1000):'Time unavailable'}</span></div><h3>${esc(n.headline)}</h3><small>${esc((n.supportingSources||[n.source]).join(' + '))} · ${esc(n.freshness)}</small>${n.url?`<button class="btn small ghost" data-url="${esc(n.url)}">Open Source</button>`:''}</article>`).join('')}</div>${x.reactions.slice(0,3).map(r=>`<div class="compact-row"><b>${esc(r.eventType)} reaction</b><span>${esc(r.phase)} · ${esc(r.state)}${num(r.movePct)?` · ${pctSigned(r.movePct)}`:''}</span></div>`).join('')}</section>`}
function eventOperationalStatusMarkup(){const e=eventIntel(),h=e.sourceHealth||{};return `<section class="settings-section"><div class="section-heading-row"><div><h2>Event Intelligence Operational Status</h2><p>Derived v16.2 intelligence reuses canonical jobs; no duplicate provider polling is introduced.</p></div>${eventIntelStateChip(e?.decision?.marketRisk||'UNKNOWN')}</div><div class="maintenance-health-grid">${[['News Intelligence',h.news],['Economic Calendar',h.macroEvents],['Event Mode',h.eventMode],['Catalyst Watch',h.catalystWatch]].map(([k,v])=>maintenanceHealthCard(k,v||'unknown')).join('')}</div></section>`}
function v168SeasonalityRows(x){const months=(x?.monthly||[]).filter(m=>m.state==='AVAILABLE');const current=months.filter(m=>m.currentYearReturnPct!=null);const focus=(current.length?current:months).slice(0,6);return `<div class="compact-list">${focus.map(m=>`<div class="compact-row"><b>${esc(m.label)} · n=${num(m.sampleCount)}</b><span>avg ${m.averageReturnPct==null?'—':pctSigned(m.averageReturnPct)} · median ${m.medianReturnPct==null?'—':pctSigned(m.medianReturnPct)} · +freq ${m.positiveFrequencyPct==null?'—':num(m.positiveFrequencyPct).toFixed(0)+'%'} · best ${m.bestReturnPct==null?'—':pctSigned(m.bestReturnPct)} · worst ${m.worstReturnPct==null?'—':pctSigned(m.worstReturnPct)}${m.currentYearReturnPct==null?'':` · ${new Date().getFullYear()} ${pctSigned(m.currentYearReturnPct)} ${esc(m.currentYearObservation||'')}`}</span></div>`).join('')||'<div class="empty">Insufficient monthly sample depth.</div>'}</div>`}
function marketValidationLearningMarkup(){const v=runtime?.validationLearning||{},s=v.seasonality?.symbols||{},x=v.concentration||{},pairs=(x.pairs||[]).filter(p=>p.state==='HIGH'||p.state==='ELEVATED').slice(0,5),groups=(x.concentrations||[]).filter(g=>g.kind==='SECTOR'||g.kind==='INDUSTRY').slice(0,5);return `<section class="settings-section"><div class="section-heading-row"><div><span class="eyebrow">Validation & Learning · v16.8</span><h2>10-Year Seasonality & Candidate Concentration</h2><p>SPY/QQQ month-of-year distributions use the existing canonical 10-year daily history path. Current-year comparison is separate; none of it changes deterministic Action/Score.</p></div></div><div class="summary-grid"><article class="card"><small>SPY Seasonality</small><h3>${esc(s.SPY?.state||'UNAVAILABLE')}</h3><p>${num(s.SPY?.dailyBars)} bars · ${esc(s.SPY?.sampleFrom||'—')} → ${esc(s.SPY?.sampleTo||'—')}</p>${v168SeasonalityRows(s.SPY)}</article><article class="card"><small>QQQ Seasonality</small><h3>${esc(s.QQQ?.state||'UNAVAILABLE')}</h3><p>${num(s.QQQ?.dailyBars)} bars · ${esc(s.QQQ?.sampleFrom||'—')} → ${esc(s.QQQ?.sampleTo||'—')}</p>${v168SeasonalityRows(s.QQQ)}</article></div><div class="compact-list">${pairs.map(p=>`<div class="compact-row"><b>${esc(p.symbolA)} / ${esc(p.symbolB)}</b><span>${esc(p.state)} · r=${num(p.correlation).toFixed(2)} · n=${num(p.sampleCount)}</span></div>`).join('')}${groups.map(g=>`<div class="compact-row"><b>${esc(g.kind)} · ${esc(g.key)}</b><span>${esc((g.symbols||[]).join(', '))}</span></div>`).join('')||(!pairs.length?'<div class="compact-row"><b>Concentration</b><span>UNKNOWN / no material aligned candidate cluster</span></div>':'')}</div></section>`}
function alternativeIntel(){return runtime?.alternativeIntelligence||{sentiment:{state:'UNAVAILABLE',components:[],missing:[]},heatMap:{cells:[],expected:11,fresh:0,coveragePct:0},gex:{},community:{label:'UNTRUSTED COMMUNITY INTELLIGENCE',state:'UNAVAILABLE',items:[],untrustedExternalContent:true},oilEnergy:{state:'UNAVAILABLE',sources:[],limitations:[]}}}
function v165AltTone(v){const s=String(v||'').toUpperCase();if(/BULLISH|AVAILABLE|STRONG|POSITIVE|HIGH QUALITY/.test(s))return 'positive';if(/BEARISH|WEAK|NEGATIVE|UNAVAILABLE|ERROR/.test(s))return 'negative';if(/MIXED|PARTIAL|INDICATIVE|MODERATE|UNKNOWN/.test(s))return 'warning';return 'muted'}
function v168HeatCellsFor(h){const cells=h?.cells||[];return `<div class="v165-heat-grid">${cells.map(x=>`<article class="v165-heat-cell ${v165AltTone(x.state)}"><div><b>${esc(x.symbol)}</b><span>${esc(x.sector||x.name||'')}</span></div><strong>${x.state==='STALE'||x.state==='UNAVAILABLE'?'—':pctSigned(x.changePercent)}</strong><small>${esc(x.state||'UNAVAILABLE')} · ${esc(x.freshness||'UNAVAILABLE')}</small></article>`).join('')||'<div class="empty">No covered canonical symbols for this mode.</div>'}</div>`}
function v168HeatModes(){const h=alternativeIntel().heatMap||{},m=h.modes||{sector:h};return ['sector','watchlist','broad'].filter(k=>m[k]).map(k=>{const x=m[k];return `<section class="v168-heat-mode"><div class="section-heading-row compact"><div><h3>${esc(x.label||titleCaseText(k))}</h3><p>${esc(x.universe||'')} · ${esc(x.coverageBasis||x.detail||'')}</p></div><span class="count-pill ${num(x.coveragePct)>=70?'positive':num(x.coveragePct)>=40?'warning':'muted'}">${num(x.fresh)}/${num(x.expected)} · ${num(x.coveragePct).toFixed(0)}%</span></div>${v168HeatCellsFor(x)}</section>`}).join('')}
function v165GEXCards(){const g=alternativeIntel().gex||{},preferred=[runtime?.marketIntelligence?.selectedSymbol,'SPY','QQQ','USO'].filter(Boolean),seen=new Set(),symbols=[...preferred,...Object.keys(g)].filter(x=>{const k=String(x).toUpperCase();if(seen.has(k))return false;seen.add(k);return true}).slice(0,6);return `<div class="summary-grid">${symbols.map(sym=>{const x=g[sym]||{},strikes=(x.majorGammaStrikes||[]).slice(0,4),exp=(x.expirationGex||[]).slice(0,3),zones=(x.gammaZones||[]).slice(0,2);return `<article class="card"><small>GEX Context · ${esc(sym)} · ${esc(x.feed||'')}</small><h3>${esc(x.state||'UNAVAILABLE')} · ${esc(x.quality||'')}</h3><b>${x.state==='AVAILABLE'?`${num(x.netGex)>=0?'+':''}${compactNumber(num(x.netGex))}`:'Withheld'}</b><p>${esc(x.detail||'Gamma/OI completeness is insufficient.')}</p>${x.state==='AVAILABLE'?`<div class="compact-list">${x.gammaFlip!=null?`<div class="compact-row"><b>Structural flip-style</b><span>$${money(x.gammaFlip)} · ${esc(x.gammaFlipMethod||'signed gamma proxy')}</span></div>`:''}<div class="compact-row"><b>Major strikes</b><span>${strikes.map(v=>`$${money(v.strike)} (${compactNumber(num(v.netGex))})`).join(' · ')||'—'}</span></div><div class="compact-row"><b>Concentration</b><span>${zones.map(v=>`$${money(v.lowStrike)}–$${money(v.highStrike)} · ${num(v.sharePct).toFixed(0)}%`).join(' · ')||'—'}</span></div><div class="compact-row"><b>Expirations</b><span>${exp.map(v=>`${esc(v.expiration)} ${compactNumber(num(v.netGex))}`).join(' · ')||'—'}</span></div></div>`:''}<small>${x.state==='AVAILABLE'?`${num(x.coveragePct).toFixed(0)}% gamma+OI matched · `:''}Structural proxy only · never measured dealer positioning · deterministic impact NONE</small></article>`}).join('')||'<article class="card"><small>GEX Context</small><h3>UNAVAILABLE</h3><p>No eligible options evidence.</p></article>'}</div>`}
function v165CommunityMarkup(){const c=alternativeIntel().community||{},items=(c.items||[]).slice(0,10),clusters=(c.clusters||[]).slice(0,8);return `<section class="card full-span v165-community"><div class="card-head"><div><span class="eyebrow">${esc(c.label||'UNTRUSTED COMMUNITY INTELLIGENCE · EVIDENCE FUSION')}</span><h3>Global Community Evidence Fusion · v16.9</h3><p>Permitted/user-authorized X, Reddit, Telegram, Discord, WhatsApp and manual evidence is normalized into canonical event clusters. Reposts are deduplicated; source diversity, velocity and corroboration are contextual only.</p></div><span class="count-pill warning">${num(c.uniqueEvents)} events · ${num(c.total)} mentions</span></div><div class="compact-list"><div class="compact-row"><b>Source diversity</b><span>${num(c.sourceDiversity)} platform(s) · 1h velocity ${num(c.mentionVelocity1h)} · AI eligible ${num(c.aiEligible)}</span></div><div class="compact-row"><b>Deterministic impact</b><span>${esc(c.deterministicImpact||'NONE')} · untrusted external content</span></div></div><h4>Fused events</h4><div class="compact-list">${clusters.map(x=>`<div class="compact-row"><b>${esc(x.symbol||'MARKET')} · ${esc(x.materiality||'NORMAL')} · ${num(x.sourceDiversity)} sources</b><span>${esc(String(x.representative||'').slice(0,180))} · velocity ${num(x.mentionVelocity1h)}/h · ${x.corroborated?'corroborated':'unconfirmed'}</span></div>`).join('')||'<div class="empty">No fused community event yet.</div>'}</div><h4>Add permitted/user-authorized evidence</h4><div class="settings-grid-2"><label class="field"><span>Symbol (optional)</span><input data-community-symbol maxlength="8" placeholder="SPY"></label><label class="field"><span>Platform</span><select data-community-platform><option>X</option><option>REDDIT</option><option>TELEGRAM</option><option>DISCORD</option><option>WHATSAPP</option><option selected>MANUAL</option><option>OTHER</option></select></label><label class="field"><span>Source / channel</span><input data-community-source maxlength="80" placeholder="Watcher Guru, WallStreetBets, server/channel…"></label><label class="field"><span>Stance</span><select data-community-stance><option>BULLISH</option><option>BEARISH</option><option>MIXED</option><option selected>UNKNOWN</option></select></label><label class="field"><span>Source URL (optional)</span><input data-community-url type="url" placeholder="https://…"></label></div><label class="field"><span>Observation</span><textarea data-community-text maxlength="1200" rows="3" placeholder="Paste or summarize a permitted/user-authorized observation. Instruction-like text remains untrusted data."></textarea></label><div class="button-row"><button class="btn" data-community-add>Add Untrusted Evidence</button></div><small>Source policy controls AI eligibility and retention. Telegram/Reddit/X/Discord/WhatsApp are context-only unless an explicit permitted rights path is recorded.</small><div class="compact-list">${items.map(x=>`<div class="compact-row"><b>${esc(x.symbol||'MARKET')} · ${esc(x.platform||'OTHER')} · ${esc(x.stance||'UNKNOWN')} · ${esc(x.source||'Community')}</b><span>${esc(String(x.text||'').slice(0,180))} · ${esc(x.aiEligibility||'CONTEXT_ONLY')} <button class="btn tiny ghost" data-community-delete="${esc(x.id)}">Remove</button></span></div>`).join('')||'<div class="empty">No permitted/user-authorized community evidence recorded.</div>'}</div></section>`}
function v165AlternativeIntelligenceMarkup(){const a=alternativeIntel(),s=a.sentiment||{},h=a.heatMap||{},o=a.oilEnergy||{},w=o.wtiContext||{},br=o.brentContext||{};return `<section class="settings-section v165-alternative-intelligence"><div class="section-heading-row"><div><span class="eyebrow">Context & Alternative Intelligence · v16.9</span><h2>Sentiment, heat, GEX, Community Evidence Fusion & Oil/Energy</h2><p>Derived from canonical stores. Missing evidence degrades explicitly; none of this changes deterministic Day/Swing/Long Action or Score.</p></div><span class="count-pill ${v165AltTone(s.state)}">${esc(s.state||'UNAVAILABLE')}</span></div><div class="summary-grid"><article class="card"><small>Sentiment Composite</small><h3>${esc(s.state||'UNAVAILABLE')}</h3><b>${s.score==null?'—':`${num(s.score)>=0?'+':''}${num(s.score).toFixed(1)}`}</b><p>${esc(s.detail||'')}</p><small>Confidence ${num(s.confidence)} · ${num(s.componentsUsed)}/${num(s.componentsExpected)} components${(s.missing||[]).length?' · missing '+esc(s.missing.join(', ')):''}</small></article><article class="card"><small>Sector Heat Map</small><h3>${num(h.fresh)}/${num(h.expected)} current</h3><b>${num(h.coveragePct).toFixed(0)}% coverage</b><p>${esc(h.detail||'')}</p><small>Stale ${num(h.stale)} · missing ${num(h.missing)}</small></article><article class="card"><small>Oil / Energy · v16.9</small><h3>${esc(o.state||'UNAVAILABLE')} · ${esc(o.energySectorState||'UNAVAILABLE')}</h3><b>WTI ${w.value==null?'—':num(w.value).toFixed(2)} · Brent ${br.value==null?'—':num(br.value).toFixed(2)}</b><p>${esc(o.detail||'')}</p><small>${o.brentWtiSpread==null?'Brent-WTI spread unavailable':`Brent-WTI ${num(o.brentWtiSpread).toFixed(2)} · ${esc(o.spreadState||'')}`} · CL/BZ roll semantics ${w.continuousContract||br.continuousContract?'provider-labelled':'not fabricated'}</small></article></div><h3>Market / Sector Heat Map · v16.8 modes</h3>${v168HeatModes()}<h3>Gamma Exposure Context</h3>${v165GEXCards()}${v165CommunityMarkup()}</section>`}
