function v151ResearchReadyForAI(sym){const s=String(sym||'').toUpperCase(),pkg=runtime?.researchPackage||{};if(String(pkg.symbol||'').toUpperCase()!==s||String(pkg.state||'').toUpperCase()!=='FRESH'||!String(pkg.evidenceSnapshotId||runtime?.evidenceSnapshot?.id||''))return false;if(v151ResearchReadyBySymbol[s]===true)return true;const ts=num(runtime?.lastUpdated?.[`research-ready:${s}`]);return canonicalResearchReady(s)&&ts>0&&Date.now()-ts<=15*60*1000}
function v151AIStatus(sym){if(v151ResearchHydrating)return {label:'Research Refreshing…',disabled:true};if(!v151ResearchReadyForAI(sym))return {label:'Research Evidence Incomplete',disabled:true};const r=latestAIResultFor(sym);if(!r)return {label:'AI Second Opinion Ready',disabled:false};const current=aiEvidenceFingerprint(sym,'none');return r._fingerprint&&r._fingerprint!==current?{label:'Refresh AI Opinion',disabled:false}:{label:'AI Opinion Current',disabled:false}}
researchConfirmationCard=function(sym){const r=latestAIResultFor(sym),st=v151AIStatus(sym);if(!r)return `<section class="card research-confirmation empty-confirmation"><div><span class="eyebrow">AI Second Opinion</span><h3>${esc(st.label)}</h3><p>Sourced Research is assembled first. AI is optional and never changes deterministic Action/Score.</p></div><button class="btn" data-research-ai="${esc(sym)}" data-ai-origin="research" ${st.disabled?'disabled':''}>${st.disabled?'Refreshing…':'Ask AI'}</button></section>`;const stale=st.label==='Refresh AI Opinion';return `<section class="card research-confirmation ${String(r.verdict||'informational').toLowerCase()}"><div class="research-confirmation-head"><div><span class="eyebrow">AI Second Opinion ${stale?'· evidence changed':''}</span><h3>${esc(titleCaseText(r.verdict||'Informational'))}</h3><p>${esc(r.summary||r.nextAction||'AI review completed.')}</p></div><div class="research-confidence"><small>Confidence</small><b>${Math.round(num(r.confidence))}%</b></div></div><div class="research-confirmation-grid"><div><small>Best-fit horizon</small><b>${esc(aiHorizonLabel(r.bestFitHorizon))}</b></div><div><small>Key reasons</small><b>${esc((r.reasons||[]).slice(0,3).join(' · ')||'—')}</b></div><div><small>Risks</small><b>${esc((r.risks||[]).slice(0,3).join(' · ')||'None identified')}</b></div><div><small>Catalyst</small><b>${esc(r.catalyst||'None identified')}</b></div></div><button class="btn ${stale?'primary':'ghost'}" data-research-ai="${esc(sym)}" data-ai-origin="research">${stale?'Refresh AI Opinion':'Ask Again'}</button><p class="research-footnote">AI reviewed the evidence snapshot available at generation time. Material evidence changes are never silently re-sent.</p></section>`}
