 const symbols=allResearchSymbols();if(!researchSymbol)researchSymbol=symbols[0]||state?.ui?.selectedTicker||'SPY';const qs=quoteState(researchSymbol),tabs=[['overview','Overview'],['earnings','Earnings'],['fundamentals','Fundamentals'],['sec','SEC & Ownership'],['catalysts','Catalysts'],['technical','Technical Context']],map={overview:researchOverview,earnings:researchEarningsV2,fundamentals:researchFundamentals,sec:researchSECAndOwnership,catalysts:researchCatalysts,technical:researchTechnicals},body=(map[researchTab]||researchOverview)(researchSymbol),originLabel=researchOrigin==='day'?'Day Trade':researchOrigin==='swing'?'Swing':researchOrigin==='long'?'Long-Term':researchOrigin==='discovery'?'Discovery':researchOrigin==='ai'?'AI Copilot':researchOrigin==='maintenance'?'Maintenance':'Dashboard',aiSt=v151AIStatus(researchSymbol),freshLabel=v151ResearchHydrating?'REFRESHING':(qs.tone==='live'||String(qs.label||'').toUpperCase()==='CURRENT'?'CURRENT':qs.label);
