function v151ExceptionLink(x){const target=String(x.target||'research'),sym=String(x.symbol||'');return sym?`<button class="btn tiny ghost" data-readiness-drill="${esc(target)}:${esc(sym)}">Review</button>`:''}
function v174SeverityRank(value){const s=String(value||'MEDIUM').toUpperCase();return s==='CRITICAL'?0:s==='HIGH'?1:s==='MEDIUM'?2:3}
function v174ExceptionParts(x){const reason=String(x?.reason||'Requires review').trim(),source=String(x?.source||'').trim().toUpperCase(),sym=String(x?.symbol||'').trim();if(sym&&source==='MARKET OPEN PREP'){const known=new Set(['LIQUIDITY RISK','EVENT RISK','EXTENDED']);const parts=reason.split(/\s*·\s*/).map(v=>v.trim().toUpperCase()).filter(v=>known.has(v));if(parts.length)return parts}return [reason]}
function v174PreparationExceptionGroups(rows){const groups=new Map();(rows||[]).forEach((x,order)=>{v174ExceptionParts(x).forEach(reason=>{const severity=String(x?.severity||'MEDIUM').toUpperCase(),source=String(x?.source||''),target=String(x?.target||'research'),key=[severity,source,target,reason].join('|');if(!groups.has(key))groups.set(key,{reason,severity,source,target,members:[],order});groups.get(key).members.push({...x,reason})})});return [...groups.values()].sort((a,b)=>v174SeverityRank(a.severity)-v174SeverityRank(b.severity)||Number(Boolean(b.members.some(x=>x.symbol)))-Number(Boolean(a.members.some(x=>x.symbol)))||b.members.length-a.members.length||a.order-b.order)}
function v174ExceptionMemberMarkup(x){return `<div class="readiness-exception-member"><div><b>${esc(x.symbol||'Market')}</b><span>${esc(x.source||'')} ${x.updatedAt?'· '+ageText(Date.now()-num(x.updatedAt)):''}</span></div>${v151ExceptionLink(x)}</div>`}
function v174ExceptionGroupMarkup(g){const tone=String(g.severity||'medium').toLowerCase(),members=g.members||[],symbols=[...new Set(members.map(x=>String(x.symbol||'')).filter(Boolean))];if(members.length===1){const x=members[0];return `<div class="readiness-exception ${tone}"><div><b>${esc(x.symbol||'Market')} · ${esc(g.reason)}</b><span>${esc(g.source||'')} ${x.updatedAt?'· '+ageText(Date.now()-num(x.updatedAt)):''}</span></div>${v151ExceptionLink(x)}</div>`}return `<details class="readiness-exception-group ${tone}"><summary><span><b>${esc(g.reason)}</b><small>${esc(g.source||'Shared readiness cause')}</small></span><em>${symbols.length||members.length} ${symbols.length===1?'symbol':'symbols'}</em></summary><div class="readiness-exception-members">${members.map(v174ExceptionMemberMarkup).join('')}</div></details>`}
function v174PreparationExceptionsMarkup(rows){const source=rows||[];if(!source.length)return '';const groups=v174PreparationExceptionGroups(source),shown=groups.slice(0,5),rest=groups.slice(5),label=`Requires Review · ${source.length} exception${source.length===1?'':'s'} · ${groups.length} grouped cause${groups.length===1?'':'s'}`;return `<div class="readiness-exceptions"><small>${esc(label)}</small>${shown.map(v174ExceptionGroupMarkup).join('')}${rest.length?`<details class="readiness-exception-more"><summary>View all ${rest.length} additional risk group${rest.length===1?'':'s'}</summary><div>${rest.map(v174ExceptionGroupMarkup).join('')}</div></details>`:''}</div>`}
