function tradingReadinessJobsMarkup(){const reactions=Object.values(runtime?.catalystReactions||{}).sort((a,b)=>num(b.updatedAt)-num(a.updatedAt));return `<section class="settings-section trading-readiness-jobs"><div class="section-heading-row"><div><h2>Trading Readiness & Catalyst Jobs</h2><p>Rich operational detail lives here; the side panel remains a compact status/control surface.</p></div><span class="count-pill">${reactions.filter(x=>x.state!=='COMPLETE').length} active reactions</span></div><div class="readiness-job-grid">${v151PreparationDetail('pre-market-prep')}${v151PreparationDetail('market-open-prep')}${v151PreparationDetail('catalyst-watch')}</div>${reactions.length?`<div class="catalyst-reaction-maintenance"><div class="section-heading-row compact"><div><h3>Catalyst Reaction Lifecycle</h3><p>Triggered events persist through premarket, opening, 5/15/30/60m and session reaction.</p></div></div><div class="catalyst-reaction-grid">${reactions.slice(0,12).map(c=>`<article><div><b>${esc(c.symbol)}</b><span>${esc(c.phase||c.state||'')}</span></div><small>${esc(c.triggerType||'Catalyst')} · ${esc(c.trigger||'')}</small><div class="reaction-metrics"><span>Gap <b>${pctSigned(c.gapPercent)}</b></span><span>Move <b>${pctSigned(c.movePercent)}</b></span><span>RVOL <b>${num(c.relativeVolume).toFixed(2)}×</b></span><span>Spread <b>${num(c.spreadPct).toFixed(2)}%</b></span><span>VWAP <b>${esc(c.vwapState||'—')}</b></span><span>Open Range <b>${esc(c.openingRangeState||'—')}</b></span><span>State <b>${esc(c.holdFadeState||'—')}</b></span></div><div class="reaction-window-line">${['5m','15m','30m','60m','session'].map(k=>`<span>${k} <b>${c.reactionPercent&&c.reactionPercent[k]!=null?pctSigned(c.reactionPercent[k]):'—'}</b></span>`).join('')}</div><button class="btn tiny ghost" data-readiness-drill="research:${esc(c.symbol)}">Open Research</button></article>`).join('')}</div></div>`:''}</section>`}
