 const weekly=`<section class="card maintenance-hero"><span class="eyebrow">Weekly Maintenance</span><div class="maintenance-summary-grid"><div class="maintenance-summary-panel"><small>Last run</small><b>${last?maintenanceTimePair(last):'Not run yet'}</b></div><div class="maintenance-summary-panel"><small>Next recommended</small><b>${next?maintenanceTimePair(next):'Run a baseline diagnostic when convenient.'}</b></div><div class="maintenance-summary-panel maintenance-action-panel"><button class="btn primary" data-run-maintenance>Run Weekly Maintenance</button></div></div></section>`;
 const system=`<section class="settings-section"><div class="section-heading-row"><div><h2>System Health / Maintenance Results</h2><p>Read-only integrity checks produced by Weekly Maintenance.</p></div><span class="count-pill health-status-pill">${esc(headerDataHealth().label)}</span></div>${maintenanceChecksMarkup()}</section>`;
